Let $(c_p)_{p\in\mathbb{N}}$ be a sequence of complex numbers, $\alpha \geqslant 1$ be a real number, and $\beta,C\in\mathbb{C}$.
\begin{itemize}
	\item If the following limit exists
	\begin{align}
	\lim_{p\to\infty}
	p^{-\alpha+1}(v_t-v_s)^{p-\beta}\cdot c_p =
	C\cdot (v_t-v_s)^{-\alpha},
	\end{align}
	then the convergent power series $f(\xi)=\sum_{p=0}^\infty c_p(v_t-\xi)^{p-\beta}$ can be analytically continued along the segment $[v_s,v_t]$ in the reverse direction, such that
	\begin{align}

	f(\xi)= C\cdot
	(\xi-v_s)^{-\alpha}(\alpha-1)! 
	+ o((\xi-v_s)^{-\alpha}),\quad
	\xi\to v_s,\xi\in[v_s,v_t].
	\end{align}
	Here we fixed the arguments 
    $\theta_s=\theta_t=\arg(v_t-v_s)$,
    making $[v_s,v_t]$ a path class with arguments.




	\item If the following limit exists
	\begin{align}
	\lim_{p\to\infty}
	p^{-\alpha+1}(v_s-v_t)^{-p-\beta}\cdot c_p =
	C\cdot (v_s-v_t)^{-\alpha},
	\end{align}
	then the convergent power series $f(\xi)=\sum_{p=0}^\infty c_p(\xi-v_t)^{-p-\beta}$ can be analytically continued along the ray 
    $[v_s,\infty \mathrm{e}^{\mathrm{i} \arg(v_s-v_t)})$
    in the reverse direction, such that
	\begin{align}
	f(\xi)= C\cdot
	(\xi-v_s)^{-\alpha}(\alpha-1)!
	+ o((\xi-v_s)^{-\alpha}),\quad
	\xi\to v_s,
	\xi\in [v_s,\infty \mathrm{e}^{\mathrm{i} \arg(v_s-v_t)}).
	\end{align}
	\[ \raisebox{-0.76491908446748\height}{\includegraphics[width=3.8705562114653cm,height=0.904843893480257cm]{Raysast.pdf}}\]
	Here we fixed the arguments
    $\theta_s=\theta_\infty=\arg(v_s-v_t)$, 
    making $[v_s,\infty \mathrm{e}^{\mathrm{i} \arg(v_s-v_t)})$ a path class with arguments.
\end{itemize}

If $A_{11},\ldots,A_{\nu\nu}$ are all non-resonant, then system (2.1) has a unique formal series solution of the following form
\begin{align}
{F}^{[\infty]}(z) = {H}^{[\infty]}(z) \cdot z^{\delta_u A} \mathrm{e}^{u z},
\end{align}
where 
\begin{equation*}
{H}^{[\infty]}(z) = 
I+ \sum_{p=1}^\infty {H}_p^{[\infty]} z^{-p},
\end{equation*}
is a formal power series of $n\times n$ matrices. 
The solution ${F}^{[\infty]}(z)$ is
called the \textbf{canonical formal fundamental solution at $z=\infty$}.
For $k=1,\ldots,\nu$, we have
\begin{subequations}
\begin{align}

({H}_p^{[\infty]})_{\hat{k}k} & =
\left(
\overleftarrow{\prod_{m=1}^{p-1}}
L_k(m-A_{kk}^{\bm{r}})
\right)\cdot
\left(
\frac{1}{u_kI-u_{\hat{k}\hat{k}}}A_{\hat{k}k}
\right),\\

({H}_p^{[\infty]})_{kk} & = -
\frac{1}{p-A_{kk}^{\bm{r}}+A_{kk}} A_{k\hat{k}}
\left(
\overleftarrow{\prod_{m=1}^{p-1}}
L_k(m-A_{kk}^{\bm{r}})
\right)\cdot
\left(
\frac{1}{u_kI-u_{\hat{k}\hat{k}}}A_{\hat{k}k}
\right),
\end{align}
\end{subequations}
and we called $\delta_u A$ the \textbf{formal monodromy matrix} of ${F}^{[\infty]}(z)$, where $L_k(z)$ is defined in (2.5),
$L_k(m-A_{kk}^{\bm{r}})$ is defined in (2.3).

Suppose that none of the elements $u_1,\ldots,u_\nu$ 
lie inside the segment $[u_s,u_t]$, then we have 
\begin{align}
    \mathcal S_{u,A}([u_s,u_t],-\tau,-\tau) =
    (S_{[\tau]})_{st}.




\end{align}

For $\xi\to\infty$,
we have the following connection formula

\begin{align}
    (\mathcal L_{d} {F}^{[0]})(\xi)
    \frac{1}
    {(A-I)!(-A)!} =
    (\mathcal B_d {F}_d)(\xi)\cdot
    C_d\left(\frac{u_k-\xi}{\xi-u_k}
    \right)^A,\quad
    \arg(u_k-\xi)\in(-d-\pi,-d+\pi).
\end{align}
The monodromy factor of $\mathcal B_d {F}_d$ on 
$\mathbb{C}_d^{\mathcal B}(u)$ at $\xi=u_s$ (see Definition 2.8) is

\begin{align}
    U_d^{[m]} = \left\{
    \begin{array}{ll}
    (I-E_{ss}(S_d^\pm -
    \mathrm{e}^{\mp 2\pi\mathrm{i}\delta_u A} S_d^\mp))^{\pm 1}, 
    & s\neq\infty\\
    \mathrm{e}^{-2\pi\mathrm{i} M_d}, 
    & s=\infty
    \end{array}\right..
\end{align}
}

If $A$ is non-resonant, then system (2.1) has a unique formal series solution of the following form
\begin{align}
{F}^{[0]} (z) = 
{H}^{[0]} (z) \cdot z^A =
\left(
I+ \sum_{p=1}^\infty {H}_p^{[0]} z^{p}
\right) \cdot z^A,
\end{align}
The series (2.11) is a convergent series with an infinite radius of convergence, called the \textbf{canonical fundamental solution at $z=0$}. If we introduce
\begin{align}
{H}^{[k]}(z) & = I+ \sum_{p=1}^\infty {H}_p^{[k]} z^{p}
:= {H}^{[0]}(z) \mathrm{e}^{-u_k z},\quad
k = 0,1, \ldots, \nu,
\end{align}
then we have for $k=1,\ldots,\nu$, 
\begin{subequations}
\begin{align}

({H}^{[k]}_p)_{\hat{k}\ast} &=
\left(
\overleftarrow{\prod_{m=-p}^{-1}}
L_k(m-A^{\bm{r}})
\right)^{-1}
\cdot I_{\hat{k}\ast},\\

({H}^{[k]}_p)_{k\ast} &= -
\frac{1}{-p-A^{\bm{r}}+A_{kk}} A_{k\hat{k}}
\left(
\overleftarrow{\prod_{m=-p}^{-1}}
L_k(m-A^{\bm{r}})
\right)^{-1}
\cdot I_{\hat{k}\ast};
\end{align}
for $k=0$, we conveniently assume that $u_k=0$, and we have
\begin{align}

{H}_p^{[0]} = 
\left(
\overleftarrow{\prod_{m=-p}^{-1}}
L_0(m-A^{\bm{r}})
\right)^{-1}
\cdot I,
\end{align}
\end{subequations}
where $L_0(z)$ is defined in (2.5).

Denote $\arg(u_t-u_s)=-\tau$.
Suppose that none of $u_i$ lies on the segment determined by $u_s$ and $u_t$,
then we have the following results
\begin{subequations}
\begin{align}
    \frac{
	(S_{[\tau]})_{st}
	}{2\pi\mathrm{i}} & =
    (u_t-u_s)^{A_{ss}}
	(\mathscr L_t^+(1-A_{tt}^{\bm{r}})^{-1})_{s \hat{t}} \cdot
	\left(\frac{1}{u_tI-u_{\hat{t}\hat{t}}}A_{\hat{t}t}\right),
    \\
    \frac{
	(S_{[\tau]})_{st}
	}{2\pi\mathrm{i}}
    & =
    \left(A_{s \hat{s}}\right)\cdot
	\mathscr L_s^-(-A_{ss}^{\bm{l}})_{\hat{s} t}
    (u_t-u_s)^{-A_{tt}}.

\end{align}
If we additionally require that none of $u_i$ lies on the line determined by $u_s$ and $u_t$, then we have the following results
\begin{align}

    ({C}_{\tau\pm\varepsilon}^{-1})_{\ast s} & =
    \left(I_{\ast \hat{t}}(u_tI_{\hat{t}\hat{t}}-u_{\hat{t}\hat{t}})\right) \cdot
	\mathscr L_t^+(1-A^{\bm{l}})_{\hat{t}s}
    (u_t-u_s)^{-A_{ss}},\\

    ({C}_{\tau\pm\varepsilon})_{t \ast} & =
    (u_t-u_s)^{A_{tt}}
    (\mathscr L_s^-(-A^{\bm{r}})^{-1})_{t\hat{s}} \cdot
	\left(I_{\hat{s}\ast}\right).
\end{align}
\end{subequations}

For $j\neq k$ and
anti-Stokes arguments $(\tau_i)_{i\in\mathbb{Z}}$,
\begin{itemize}
    \item the diagonal blocks of $S_{[\tau_i]}$ are identity matrices;
    \item if $-\arg(u_k-u_j)\notin \tau_i+2\pi\mathbb{Z}$, 
          then $(S_{[\tau_i]})_{jk}=0$;
    \item if $-\arg(u_k-u_j)\in \tau_i+2\pi\mathbb{Z}$, 
          then $(S_{[\tau_i]})_{jk}=(S_{\tau_i\pm\varepsilon})_{jk}$,
          where $\varepsilon>0$ sufficiently small;
    \item take $l\in\mathbb{Z}$ such that $\tau_{i+l}=\tau_i+\pi$.
          If $d\in(\tau_i,\tau_{i+1})$, then
          \begin{align}
              S_d^+ = S_{[\tau_{i+l}]} \cdots
                      S_{[\tau_{i+2}]}S_{[\tau_{i+1}]},\quad
              S_d^- = S_{[\tau_{i-l+1}]}^{-1} \cdots
                      S_{[\tau_{i-1}]}^{-1}S_{[\tau_{i}]}^{-1}.
          \end{align}
\end{itemize}

For $\hbar\notin \mathbb{Q}$, the system (1.1) has a unique formal solution
\begin{align}
\hat{F}(z)= \left(I+\sum_{p=1}^\infty {H}_p z^{-p}\right)\cdot 
\mathrm{e}^{u z}
z^{-\hbar\delta\mathbf{E}},\quad
\delta\mathbf{E}=\ensuremath{\operatorname{diag}}(e_{11},\ldots,e_{\nu\nu}),
\end{align}
where $I$ is the identity matrix, and the coefficients $H_p\in\operatorname{Mat}_{n}
(U(\mathfrak{gl}_\nu{}))$ are recursively determined by the relations
\begin{align}
    ({H}_{1})_{i k} = 
    -\frac{\hbar e_{ik}}{u_k-u_i}
    ,\quad
    ({H}_{p+1})_{i k} = 
    \sum_{j\neq k}
    T_k(p)_{ij}
    ({H}_{p})_{j k}
    ,\quad
    ({H}_{p})_{k k} =
    \sum_{j\neq k}
    \frac{\hbar e_{k j}}{p} 
    ({H}_{p})_{j k}.
\end{align}
Here for any $\lambda\in \mathbb{C}\setminus\{0\}$, 
$T_k(\lambda)$ is an $(\nu-1)\times(\nu-1)$-matrix with entries
\begin{align}
    T_k(\lambda)_{ij}:=
    \frac{1}{u_k-u_i}
    \left(
    (\lambda+\hbar(e_{kk}+1))\delta_{ij}
    - \hbar e_{ij}
    - \hbar^2\frac{e_{ik}e_{kj}}{\lambda}
    \right)\in U(\mathfrak{gl}_\nu),\quad
    i,j\in \{ 1,\ldots,\nu\}\setminus \{k\}.
\end{align}





















Furthermore, $T_k(\lambda)$ satisfies
the Yangian relations (1.2) of $Y_{\hbar}(\mathfrak{gl}_{\nu-1})$

, i.e., 
for indices $i_0, i_j, j_0, j_1$,
\begin{align}
\frac{1}{\hbar}
[T_k(\lambda_1)_{i_1 i_0},
 T_k(\lambda_2)_{j_1 j_0}] & =
\frac{T_k(\lambda_2)_{j_1 i_0}
	  T_k(\lambda_1)_{i_1 j_0}-
	  T_k(\lambda_1)_{j_1 i_0}
	  T_k(\lambda_2)_{i_1 j_0}}
{\lambda_1-\lambda_2}\in U(\mathfrak{gl}_\nu).






\end{align}

Suppose that none of $u_k$, for all $k\ne i,j$, lies on the segmant determined by $u_i$ and $u_j$, then the $(i,j)$-entry of the Stokes matrix $S_{[\tau]}$ associated to the anti-Stokes direction $\tau=-\arg(u_j-u_i)$, as elements in ${\rm End}(V)$, is given by 
(see Section 3 for the meaning of the infinite matrix product)
\begin{align*}
   (u_j-u_i)^{\hbar e_{ii}}
    \frac{(S_{[\tau]})_{ij}}{2\pi\mathrm{i}}
    (u_j-u_i)^{-\hbar e_{jj}} & =
    \lim_{p\to\infty}
    \frac{(u_j-u_i)^{p+1}}{p!}
    p^{\hbar(e_{ii}-e_{jj}-1)}
    \left(
    \overleftarrow{\prod_{m=1}^{p}}
	T_j(m)
    \right)_{i\hat{j}}
    \left(
    -\frac{1}{u_jI-u_{\hat{j}\hat{j}}}
    \hbar \mathbf{E}_{\hat{j}j}
    \right),\\
    (u_j-u_i)^{\hbar e_{ii}}
    \frac{(S_{[\tau]})_{ij}}{2\pi\mathrm{i}}
    (u_j-u_i)^{-\hbar e_{jj}}
    & =
    \lim_{p\to\infty}
    \frac{(u_j-u_i)^{p}}{p!}
    \left(-\hbar \mathbf{E}_{i\hat{i}} \right)
    \left(
    \overleftarrow{\prod_{m=-p}^{-1}}
	T_i(m)
	\right)_{\hat{i} j}
  	p^{\hbar(e_{ii}-e_{jj}+1)},
\end{align*}
where $\overleftarrow{\prod_{m=1}^{p}}T_j(m) := T_j(p)\cdots T_j(2)T_j(1)$.
Here for a matrix $A$, 
we denote $A_{\hat{i}j}$ as the $j$-th column of $A$ without the $i$-th row; 
$A_{i\hat{j}}$ as the $i$-th row of matrix $A$ without the $j$-th column.

Suppose that
\begin{align}
    \frac{\varepsilon_B}{2}:=
    \max\{\|B_{11}\|,\ldots,\|B_{\mu\mu}\|\} < \frac{1}{4}.
\end{align}
For $z\notin \mathbb{Z}^{<0} + \Lambda$, 
if $|v_s|<\varepsilon |v_k|$
for every $k\neq s$, and for some
sufficiently small $\varepsilon(z,\tilde{B})>0$,
then the following limit exists
\begin{align}
    \lim_{p\to\infty}
	p^{-zI-B_{ss}}
	\frac{v_s^{-p}}{p!}
	\left(
	\overleftarrow{\prod_{m=1}^{p}}
	v \tilde{B}(m+z)
	\right)_{s\ast}.
\end{align}
For $z\notin \mathbb{Z}^{>0} + \Lambda$, 
if $|v_s|<\varepsilon |v_k|$
for every $k\neq s$, and 
sufficiently small $\varepsilon(z,\tilde{B})>0$,
then the following limit exists
\begin{align}
    \lim_{p\to\infty}
	\left(
	\overleftarrow{\prod_{m=-p}^{-1}}
	v \tilde{B}(m+z)
	\right)_{\ast s}
	\frac{(-v_s)^{-p}}{p!}
  	p^{zI+B_{ss}}.
\end{align}

The wedge

defined in (4.19) satisfies 
the right Leibniz law.
For the representative elements of path class with arguments,
\begin{align*}
    \tilde{\gamma}_{s_1m} =
    (\gamma_{s_1m}, \theta_s^{(1)}, \theta_m),\quad
    \tilde{\gamma}_{mt_1} =
    (\gamma_{mt_1}, \theta_m, \theta_t^{(1)}),\quad
    \tilde{\gamma}_{s_2t_2} =
    (\gamma_{s_2t_2}, \theta_s^{(2)}, \theta_t^{(2)}),
\end{align*}
we have
\begin{align}
    (\tilde{\gamma}_{s_1m}
     \tilde{\gamma}_{mt_1})
    \wedge \tilde{\gamma}_{s_2t_2} & :=
    (\tilde{\gamma}_{s_1m} \overset{r}{\circ} 
    \tilde{\gamma}_{mt_1})
    \wedge \tilde{\gamma}_{s_2t_2} -
    (\tilde{\gamma}_{s_1m} \overset{l}{\circ} 
    \tilde{\gamma}_{mt_1})
    \wedge \tilde{\gamma}_{s_2t_2}\\
    & =
    (\tilde{\gamma}_{s_1m}
     \wedge \tilde{\gamma}_{s_2t_2} )
     \tilde{\gamma}_{mt_1} +
     \tilde{\gamma}_{s_1m}
    (\tilde{\gamma}_{mt_1}
     \wedge \tilde{\gamma}_{s_2t_2} ).
\end{align}

Let us introduce the matrix 
$\mathscr{T}$ with entries
\begin{equation}
    \mathscr{T}_{ij} \ :=
    \lim_{p\to\infty}
    \frac{(u_j-u_i)^{p+1}}{p!}
    p^{\hbar(e_{ii}-e_{jj}-1)}
    \left( \overleftarrow{\prod_{m=1}^{p}}
	T_j(m)
    \right)_{i\hat{j}}
    \left(
    -\frac{1}{u_jI-u_{\hat{j}\hat{j}}}
    \hbar \mathbf{E}_{\hat{j}j}
    \right),









\end{equation}
where $T_k(m)$ is defined as in (1.5). Then
\begin{enumerate}
    \item For distinct indices $s_1,t_1,s_2,t_2$ and
    disjoint segments
    $[u_{s_1},u_{t_1}]\cap [u_{s_2},u_{t_2}] = \varnothing$, 
    we have
    \begin{align}
    \mathscr{T}_{s_1 t_1} 
    \mathscr{T}_{s_2 t_2} -
    \mathscr{T}_{s_2 t_2} 
    \mathscr{T}_{s_1 t_1} = 0;
    \end{align}

    \item For distinct indices $s_1,t_1,s_2,t_2$ and disjoint segments
    $[u_{s_1},u_{t_1}]\cap [u_{s_2},u_{t_2}] \neq \varnothing$,
    $\arg(u_{t_2}-u_{s_2}) -
    \arg(u_{t_1}-u_{s_1}) \in (0,\pi)$, we have
    \begin{align}
    \frac{
    \mathscr{T}_{s_1 t_1} 
    \mathscr{T}_{s_2 t_2} -
    \mathscr{T}_{s_2 t_2} 
    \mathscr{T}_{s_1 t_1}
    }{q-q^{-1}} =
    \frac{
    (u_{t_2}-u_{s_1})^{\hbar( e_{t_2t_2}-e_{s_1s_1}+1 )}
    (u_{t_1}-u_{s_2})^{\hbar( e_{t_1t_1}-e_{s_2s_2}+1 )}
    }{
    (u_{t_1}-u_{s_1})^{\hbar( e_{t_1t_1}-e_{s_1s_1}+1 )}
    (u_{t_2}-u_{s_2})^{\hbar( e_{t_2t_2}-e_{s_2s_2}+1 )}
    }
    \mathscr{T}_{s_1 t_2}
    \mathscr{T}_{s_2 t_1};
    \end{align}

    \item For distinct indices $s,m,t$, we have
    \begin{subequations}
    \begin{align}
    \frac{
    \left(\frac
    {u_s-u_m}{u_t-u_s}
    \right)^\hbar
    \mathscr{T}_{sm} \mathscr{T}_{mt} -
    \left(\frac
    {u_t-u_m}{u_t-u_s}
    \right)^\hbar
    \mathscr{T}_{mt} \mathscr{T}_{sm}
    }{(q-q^{-1})/2\pi\mathrm{i}} & =
    -
    \left(\frac
    {u_m-u_s}{u_t-u_s}
    \right)^{\hbar(e_{ss}-e_{mm})}
    \left(\frac
    {u_t-u_m}{u_t-u_s}
    \right)^{\hbar(e_{mm}-e_{tt})}
    \mathscr{T}_{st},\\
    \mathscr{T}_{ms} \mathscr{T}_{mt} -
    \left(\frac
    {u_m-u_s}{u_t-u_m}
    \right)^\hbar
    \mathscr{T}_{mt} \mathscr{T}_{ms}
    & = 0,\\
    \mathscr{T}_{sm} \mathscr{T}_{tm} -
    \left(\frac
    {u_m-u_s}{u_t-u_m}
    \right)^\hbar
    \mathscr{T}_{sm} \mathscr{T}_{tm}
    & = 0,\\

    \frac{
    \mathscr{T}_{st} \mathscr{T}_{ts} -
    \mathscr{T}_{ts} \mathscr{T}_{st}
    }{(q-q^{-1})/2\pi\mathrm{i}} & = 
    \frac{
    q^{e_{ss}-e_{tt}} -
    q^{e_{tt}-e_{ss}}
    }{2\pi\mathrm{i}}.
    \end{align}
    \end{subequations}  
\end{enumerate}
We require that for arbitrary indices 
$s_1,t_1,s_2,t_2$ (not necessarily distinct),
the arguments satisfy
$\arg(u_{t_2}-u_{s_2}) -
 \arg(u_{t_1}-u_{s_1}) \in (-\pi,\pi)$.
